package vn.rtr.aeris.native90;
import android.os.*;import android.view.*;import android.hardware.input.InputManager;import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Offline diagnostic model only. No flight/control sink. Native elapsed clock owns freshness. */
public final class Diagnostics90 implements InputManager.InputDeviceListener {
 private final ShellActivity owner;private final Handler h=new Handler(Looper.getMainLooper());private final String session=UUID.randomUUID().toString();private final InputModel input=new InputModel(session);private final VideoWatch89 video=new VideoWatch89();private BenchJournal89 journal;private InputManager manager;private boolean foreground=false,focused=false,watchKeys=false,closed=false;private String fatal="",lastInput="";private int epoch=0,keyCount=0,motionCount=0;private long lastFrameLog=-1;private final String fixtureSha;
 private static long now(){return SystemClock.elapsedRealtime();}
 private static JSONObject obj(Object... a){JSONObject o=new JSONObject();try{for(int i=0;i<a.length;i+=2)o.put((String)a[i],a[i+1]==null?JSONObject.NULL:a[i+1]);}catch(Exception e){throw new IllegalStateException(e);}return o;}
 public Diagnostics90(ShellActivity a)throws Exception{owner=a;try(InputStream in=a.getAssets().open("cockpit/synthetic.webm")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>1048576)throw new IOException("FIXTURE_BOUND");}fixtureSha=BenchJournal89.sha(out.toByteArray());}if(!fixtureSha.equals("317747904d0dba4d52afd987b92f19acab70d99766ac0db1f8d2134b8acd9a18"))throw new IOException("FIXTURE_SHA");journal=new BenchJournal89(new File(a.getFilesDir(),"diagnostics90"),session);record("SESSION",obj("source","SYNTHETIC_FIXTURE","fixtureSha256",fixtureSha,"operational",false,"authorityRestorable",false,"mediaPath","ANDROID_WEBVIEW_RVFC","sourceId",BuildInfo90.SOURCE_ID));manager=(InputManager)a.getSystemService(Context.INPUT_SERVICE);manager.registerInputDeviceListener(this,h);h.post(ticker);}
 private synchronized JSONObject snapshot(){try{return obj("session",session,"foreground",foreground,"focused",focused,"watchKeys",watchKeys,"input",new JSONObject(input.json()),"video",new JSONObject(video.peekJson(now())),"keyCallbacks",keyCount,"rawMotionCallbacks",motionCount,"operational",false);}catch(Exception e){throw new IllegalStateException(e);}}
 private synchronized void record(String kind,JSONObject data){if(!fatal.isEmpty()||journal==null)return;try{journal.append(obj("session",session,"kind",kind,"data",data).toString(),now());}catch(Exception e){fatal="DIAGNOSTIC_LOG_BLOCKED_NO_DELETE: "+e.getMessage();watchKeys=false;epoch++;input.focus(false,now());video.stop("LOG_BLOCKED");owner.stop90("LOG_BLOCKED",video.generation);}}
 public synchronized String action(String action,String raw){try{if(raw==null||raw.getBytes(StandardCharsets.UTF_8).length>4096)throw new IOException("BODY_BOUND");JSONObject q=new JSONObject(raw);if(action.equals("status")){advance();return status();}if(!fatal.isEmpty()||closed)throw new IOException("DIAGNOSTICS_BLOCKED");if(!foreground||!focused)throw new IOException("FOREGROUND_FOCUS_REQUIRED");long g=q.optLong("generation",-1),t=now();
 switch(action){
 case "prepare":video.stop("NEW_EXPLICIT_PLAY");g=video.prepare(t);lastFrameLog=-1;record("VIDEO_PREPARE",obj("generation",g,"snapshot",snapshot()));break;
 case "prepared":if(!video.prepared(g,q.getInt("width"),q.getInt("height"),q.getLong("durationMs"),t)||!video.start(g,t))throw new IOException("METADATA_OR_GENERATION_REFUSED");record("VIDEO_STARTED",obj("generation",g,"snapshot",snapshot()));break;
 case "frame":long pts=q.getLong("mediaTimeNs");if(pts<0||pts>10000000000L)throw new IOException("MEDIA_TIMELINE_BOUND");boolean yes=video.frame(g,pts,t);record(yes?"FRAME_CALLBACK":"REJECTED_FRAME_CALLBACK",obj("generation",g,"mediaTimeNs",pts,"snapshot",snapshot()));if(!yes)throw new IOException("FRAME_REFUSED");lastFrameLog=t;break;
 case "ended":if(!video.end(g,t))throw new IOException("END_WITHOUT_CURRENT_CALLBACK_PROOF");record("VIDEO_ENDED",obj("generation",g,"snapshot",snapshot()));break;
 case "freeze":if(!video.playing()||g!=video.generation)throw new IOException("NOT_PLAYING");record("FAULT_RENDER_PAUSED",obj("generation",g,"snapshot",snapshot()));break;
 case "stop":stop("EXPLICIT_STOP");break;
 case "mock":mock();break;
 case "invalid":try{input.sample(session,"mock:local90",9,t);throw new IOException("INVALID_NOT_REJECTED");}catch(IllegalArgumentException expected){record("INVALID_AXIS_REJECTED",snapshot());}break;
 case "keys":watchKeys=q.getBoolean("enabled");record("KEY_OBSERVER",snapshot());break;
 case "selftest":record("ART_SELF_TEST",new JSONObject(ModelTest89.run()).put("runtime","ANDROID_ART"));break;
 default:throw new IOException("ACTION_REFUSED");}
 return status();}catch(Exception e){return obj("ok",false,"error",e.getMessage()).toString();}}
 private String status(){return obj("ok",true,"snapshot",snapshot(),"traceHead",journal==null?"":journal.head(),"events",journal==null?0:journal.count(),"fatal",fatal,"fixtureSha256",fixtureSha,"authorityRestorable",false).toString();}
 private synchronized void mock(){final int e=++epoch;input.attach(new InputModel.Calibration("n90-fixture","mock:local90",-1,0,1,.1,false),now());input.focus(true,now());record("MOCK_BEGIN",snapshot());for(int i=0;i<3;i++){final int index=i;h.postDelayed(()->{synchronized(this){if(e!=epoch||!foreground||!focused||closed||!fatal.isEmpty())return;input.sample(session,"mock:local90",0,now());if(index==2){input.hold(true,now());boolean got=input.acquire(now());record("MOCK_ACQUIRED",obj("acquired",got,"snapshot",snapshot()));}}},i*80);}h.postDelayed(()->{synchronized(this){if(e!=epoch||!foreground||!focused||closed||!fatal.isEmpty())return;input.sample(session,"mock:local90",.55,now());record("MOCK_AXIS",snapshot());}},240);}
 public synchronized void link(JSONObject reference){if(!foreground||!focused||!fatal.isEmpty()||closed)throw new IllegalStateException("LINK_INACTIVE_OR_BLOCKED");record("WORKSPACE_REVIEW_LINK",obj("reference",reference,"diagnosticHeadBeforeLink",journal.head(),"snapshot",snapshot(),"actualImages",0,"authorityRestorable",false));if(!fatal.isEmpty())throw new IllegalStateException(fatal);}
 private synchronized void stop(String reason){video.stop(reason);record("VIDEO_STOP",obj("reason",reason,"snapshot",snapshot()));owner.stop90(reason,video.generation);}
 public synchronized void lifecycle(boolean resumed){foreground=resumed;epoch++;watchKeys=false;input.focus(false,now());stop(resumed?"RESUMED_NO_RESTORE":"ANDROID_BACKGROUND");record(resumed?"ACTIVITY_RESUMED_NO_RESTORE":"ACTIVITY_PAUSED",snapshot());}
 public synchronized void focus(boolean value){focused=value;epoch++;watchKeys=false;input.focus(value&&foreground,now());if(!value)stop("FOCUS_LOST");record(value?"FOCUS_GAINED_NO_RESTORE":"FOCUS_LOST",snapshot());}
 private synchronized void advance(){String before=video.state;video.tick(now());if(!before.equals(video.state)&&(video.state.equals("STALLED_NO_AUTO_RESUME")||video.state.equals("PREPARE_TIMEOUT"))){record(video.state.equals("PREPARE_TIMEOUT")?"VIDEO_PREPARE_TIMEOUT":"VIDEO_STALE",snapshot());owner.stop90(video.state,video.generation);}}
 private final Runnable ticker=new Runnable(){public void run(){synchronized(Diagnostics90.this){if(closed)return;try{input.tick(now());if(!input.reason().equals(lastInput)){lastInput=input.reason();record("INPUT_STATE",snapshot());}advance();}catch(Exception e){fatal="CLOCK_OR_MODEL_BLOCKED";owner.stop90(fatal,video.generation);}h.postDelayed(this,50);}}};
 public synchronized boolean key(KeyEvent e){int k=e.getKeyCode();if(watchKeys&&foreground&&focused&&(k>=19&&k<=22||k==96||k==97)){long receipt=SystemClock.uptimeMillis(),delay=receipt-e.getEventTime();keyCount++;record("ANDROID_KEY_UNATTESTED",obj("keyCode",k,"action",e.getAction(),"source",e.getSource(),"deviceId",e.getDeviceId(),"eventUptimeMs",e.getEventTime(),"callbackUptimeMs",receipt,"dispatchDelayMs",delay>=0&&delay<=2000?delay:null,"clockDomain","ANDROID_UPTIME_MILLIS","noControlMapping",true));return true;}return false;}
 public synchronized boolean motion(MotionEvent e){if(watchKeys&&foreground&&focused&&(e.getSource()&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK&&e.getAction()==MotionEvent.ACTION_MOVE){JSONArray axes=new JSONArray();InputDevice d=e.getDevice();if(d!=null)for(InputDevice.MotionRange r:d.getMotionRanges()){if(axes.length()>=16)break;axes.put(obj("axis",r.getAxis(),"raw",e.getAxisValue(r.getAxis())));}motionCount++;record("ANDROID_JOYSTICK_RAW_UNMAPPED",obj("source",e.getSource(),"axes",axes,"physicalMappingVerified",false));return true;}return false;}
 public synchronized void onInputDeviceAdded(int id){record("INPUT_DEVICE_ADDED",obj("deviceId",id));}public synchronized void onInputDeviceChanged(int id){epoch++;input.detach(now());record("INPUT_DEVICE_CHANGED",snapshot());}public synchronized void onInputDeviceRemoved(int id){epoch++;input.detach(now());record("INPUT_DEVICE_REMOVED",snapshot());}
 public synchronized void close(){if(closed)return;epoch++;watchKeys=false;input.focus(false,now());video.stop("DESTROYED");record("ACTIVITY_DESTROYED",snapshot());closed=true;h.removeCallbacksAndMessages(null);manager.unregisterInputDeviceListener(this);try{journal.close();}catch(Exception ignored){}}
}
